import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set depositsCount to type(uint256).max - 1 by calling sendMoney many times
        // Since depositsCount starts at 0, we can just manipulate it via the contract's own logic.
        // However, there's no setter for depositsCount. We need to increase it via receive().
        // The contract has no public function to increment depositsCount easily.
        // But we can use vm.store to set the storage slot directly.
        vm.store(address(c), bytes32(uint256(1)), bytes32(type(uint256).max - 1));
        // Now depositsCount is type(uint256).max - 1
        uint256 initial_deposits = c.depositsCount();
        // Call sendMoney with 1 wei
        c.sendMoney{value: 1 wei}(address(c), 1 wei);
