pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(address(owner), 10 ether);
        vm.prank(owner);
        c.sendMoney{value: 1 wei}(address(0xdead), 0);
        vm.prank(owner);
        c.sendMoney{value: 1 wei}(address(0xdead), 0);
        uint depositsCount = c.depositsCount();
        assertTrue(depositsCount == 2);
    }
}

